for (const [language, additions] of Object.entries(v12Translations)) Object.assign(dictionaries[language], additions);

const supported = new Set(Object.keys(dictionaries));

export function resolveLanguage(preference = 'system') {
  if (supported.has(preference)) return preference;
  const browserLanguage = String(navigator.languages?.[0] || navigator.language || 'en').slice(0, 2).toLowerCase();
  return supported.has(browserLanguage) ? browserLanguage : 'en';
}

export function localeFor(language) {
  return ({ de: 'de-DE', en: 'en-GB', fr: 'fr-FR', es: 'es-ES', it: 'it-IT', nl: 'nl-NL' })[language] || 'en-GB';
}

export function applyTranslations(language) {
  const resolved = resolveLanguage(language);
  const dictionary = dictionaries[resolved];
  document.documentElement.lang = resolved;
  for (const element of document.querySelectorAll('[data-i18n]')) {
    const value = dictionary[element.dataset.i18n] || dictionaries.en[element.dataset.i18n];
    if (value) element.textContent = value;
  }
  for (const element of document.querySelectorAll('[data-i18n-placeholder]')) {
    const value = dictionary[element.dataset.i18nPlaceholder] || dictionaries.en[element.dataset.i18nPlaceholder];
    if (value) element.setAttribute('placeholder', value);
  }
  return resolved;
}

export function translate(language, key) {
  const resolved = resolveLanguage(language);
  return dictionaries[resolved]?.[key] || dictionaries.en[key] || key;
}
